import React, { useState, useRef } from 'react';
import { getUsername } from '../../keycloak';
import { useChat } from '../Chat/useChat';
import './Questions.css';

const Questions = () => {
    const [questionMode, setQuestionMode] = useState('general');
    const [newQuestion, setNewQuestion] = useState('');
    const [answerText, setAnswerText] = useState({});
    const [showQuestionSent, setShowQuestionSent] = useState(false);
    const questionSentTimerRef = useRef(null);

    const currentUser = getUsername();

    // Получаем роль из localStorage (от переключателя)
    const demoRole = localStorage.getItem('demoRole');

    // Определяем роли четко
    const isGeneralAdmin = demoRole === 'MODERATOR_ADMIN' || demoRole === 'DEVELOPER';
    const isNutritionConsultant = demoRole === 'CONSULTANT_PITANIE';
    const isSportConsultant = demoRole === 'CONSULTANT_SPORT';
    const isVyacheslav = demoRole === 'VYACHESLAV';
    const isSuperAdmin = demoRole === 'SUPER_ADMIN';
    const isUser0 = demoRole === 'USER_0';
    const isAnyAdmin = isGeneralAdmin || isNutritionConsultant || isSportConsultant || isVyacheslav || isSuperAdmin;

    const isAdmin = isGeneralAdmin || isNutritionConsultant || isVyacheslav || isSuperAdmin;

    const {
        messages: questions,
        loading,
        sendMessage,
        currentUserAuthor,
        deleteMessage
    } = useChat(null, {
        isQuestionMode: true,
        questionMode: questionMode,
        canSwitchRooms: false
    });

    const handleAskQuestion = async () => {
        if (!newQuestion.trim()) return;
        try {
            await sendMessage(newQuestion.trim());
            setNewQuestion('');
            showQuestionSentNotification();
        } catch (err) {
            alert('Не удалось отправить вопрос');
        }
    };

    const handleAnswerQuestion = async (messageId) => {
        const text = answerText[messageId];
        if (!text?.trim()) return;
        try {
            await sendMessage(`Ответ: ${text.trim()}`);
            setAnswerText(prev => ({ ...prev, [messageId]: '' }));
        } catch (err) {
            alert('Не удалось отправить ответ');
        }
    };

    const showQuestionSentNotification = () => {
        setShowQuestionSent(true);
        if (questionSentTimerRef.current) clearTimeout(questionSentTimerRef.current);
        questionSentTimerRef.current = setTimeout(() => setShowQuestionSent(false), 2000);
    };

    return (
        <div className="help-center">
            <div className="help-header">
                <h2>Вопросы и ответы</h2>

                {/* Переключатель для Обычных пользователей */}
                {(demoRole === 'USER_1' || demoRole === 'USER_2') && (
                    <div className="mode-switcher">
                        <button
                            className={`mode-btn ${questionMode === 'general' ? 'active' : ''}`}
                            onClick={() => setQuestionMode('general')}
                        >
                            Общий
                        </button>
                        <button
                            className={`mode-btn ${questionMode === 'nutrition' ? 'active' : ''}`}
                            onClick={() => setQuestionMode('nutrition')}
                        >
                            Питание
                        </button>
                        <button
                            className={`mode-btn ${questionMode === 'vyacheslav' ? 'active' : ''}`}
                            onClick={() => setQuestionMode('vyacheslav')}
                        >
                            Вячеславу
                        </button>
                    </div>
                )}
            </div>

            {!isAdmin && (
                <div className="ask-section">
                    <h3>💬 Задать вопрос</h3>
                    <div className="ask-description">
                        <p>Напишите свой вопрос в выбранный раздел</p>
                    </div>
                    <div className="ask-form">
                        <textarea
                            className="question-input"
                            placeholder="Введите ваш вопрос..."
                            value={newQuestion}
                            onChange={(e) => setNewQuestion(e.target.value)}
                            rows="4"
                        />
                        <button className="submit-button" onClick={handleAskQuestion}>
                            📤 Отправить вопрос
                        </button>
                    </div>
                </div>
            )}

            <div className="faq-section">
                <div className="faq-header-actions">
                    <h3>📋 {questionMode === 'general' ? 'Общие вопросы' : questionMode === 'nutrition' ? 'Вопросы по питанию' : 'Вопросы Вячеславу'}</h3>
                </div>

                <div className="faq-list">
                    {loading ? (
                        <div className="loading">Загрузка вопросов...</div>
                    ) : questions.length === 0 ? (
                        <div className="no-questions">
                            <p>Пока нет вопросов в этом разделе</p>
                        </div>
                    ) : (
                        questions.map((msg) => (
                            <div key={msg.id} className={`faq-item ${msg.content?.includes('Ответ:') ? 'answered' : 'pending'}`}>
                                <div className="faq-question">
                                    <strong>❓ {msg.content}</strong>
                                    <div className="question-meta">
                                        <span>👤 {msg.author || currentUserAuthor}</span>
                                        <span>📅 {new Date(msg.createdAt || msg.timestamp).toLocaleDateString()}</span>
                                    </div>
                                </div>

                                {msg.content?.includes('Ответ:') && (
                                    <div className="faq-answer">
                                        <strong>📝 Ответ:</strong>
                                        <p>{msg.content.replace('Ответ: ', '')}</p>
                                    </div>
                                )}

                                {isAdmin && !msg.content?.includes('Ответ:') && (
                                    <div className="answer-form">
                                        <textarea
                                            className="answer-input"
                                            placeholder="Напишите ответ..."
                                            value={answerText[msg.id] || ''}
                                            onChange={(e) => setAnswerText(prev => ({ ...prev, [msg.id]: e.target.value }))}
                                            rows="3"
                                        />
                                        <button className="answer-submit" onClick={() => handleAnswerQuestion(msg.id)}>
                                            ✍️ Ответить
                                        </button>
                                    </div>
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>

            {showQuestionSent && (
                <div className="question-sent-notification">
                    Вопрос отправлен
                </div>
            )}
        </div>
    );
};

export default Questions;
